import json
import sqlite3
from collections import defaultdict
from fractions import Fraction
from pathlib import Path

STEPS = ('install', 'tutorial_complete', 'first_match', 'purchase')
connection = sqlite3.connect('file:analytics.db?mode=ro', uri=True)
platforms = [row[0] for row in connection.execute('SELECT DISTINCT platform FROM users ORDER BY platform')]
funnel = {platform: dict.fromkeys(STEPS, 0) for platform in platforms}
player_events = defaultdict(lambda: defaultdict(list))
for player, step, timestamp in connection.execute('SELECT user_id, name, ts FROM events'):
    if step in STEPS:
        player_events[player][step].append(timestamp)
for player, platform in connection.execute('SELECT user_id, platform FROM users WHERE is_test = 0'):
    previous = None
    for step in STEPS:
        valid = [stamp for stamp in player_events[player][step] if previous is None or stamp >= previous]
        if not valid:
            break
        previous = min(valid)
        funnel[platform][step] += 1
biggest_drop = {}
for platform, counts in funnel.items():
    eligible = [(Fraction(counts[step], counts[STEPS[index-1]]), index, step)
                for index, step in enumerate(STEPS) if index and counts[STEPS[index-1]]]
    biggest_drop[platform] = min(eligible)[2] if eligible else None
result = {'funnel': funnel, 'biggest_drop': biggest_drop}
Path('result.json').write_text(json.dumps(result, indent=2) + '\n', encoding='utf-8')

# Independent SQL computes each first valid event by a correlated minimum.
query = '''
WITH installs AS (
 SELECT u.user_id, u.platform, MIN(julianday(e.ts)) AS stamp
 FROM users u JOIN events e ON e.user_id=u.user_id
 WHERE u.is_test=0 AND e.name='install' GROUP BY u.user_id,u.platform
), tutorials AS (
 SELECT i.*, (SELECT MIN(julianday(e.ts)) FROM events e WHERE e.user_id=i.user_id
 AND e.name='tutorial_complete' AND julianday(e.ts)>=i.stamp) AS tutorial FROM installs i
), matches AS (
 SELECT t.*, (SELECT MIN(julianday(e.ts)) FROM events e WHERE e.user_id=t.user_id
 AND e.name='first_match' AND julianday(e.ts)>=t.tutorial) AS match FROM tutorials t
), purchases AS (
 SELECT m.*, (SELECT MIN(julianday(e.ts)) FROM events e WHERE e.user_id=m.user_id
 AND e.name='purchase' AND julianday(e.ts)>=m.match) AS purchase FROM matches m
)
SELECT platform,COUNT(stamp),COUNT(tutorial),COUNT(match),COUNT(purchase)
FROM purchases GROUP BY platform
'''
verified = {row[0]: dict(zip(STEPS, row[1:])) for row in connection.execute(query)}
assert verified == funnel, (verified, funnel)
assert json.loads(Path('result.json').read_text(encoding='utf-8')) == result
print('PASS: independent SQL and Python funnel counts agree for every platform and step.')
print('PASS: result.json round-trip matches the verified result.')
print(json.dumps(result, indent=2))
for platform, counts in funnel.items():
    for index, step in enumerate(STEPS[1:], 1):
        before = counts[STEPS[index-1]]
        print(f'{platform} {step}: {counts[step]}/{before}; lost {before-counts[step]} players')


